  remove.type="button";remove.addEventListener("click",()=>{if($$(".error-entry").length>1)entry.remove();else entry.querySelectorAll("input, textarea").forEach(el=>el.value="");refreshEntryNumbers();});head.append(title,remove);
  const grid=node("div","error-entry-grid"),qLabel=node("label"),q=node("input","question-ref"),typeLabel=node("label"),select=node("select","error-type"),marksLabel=node("label"),marks=node("input","marks-lost"),pointLabel=node("label","span-2"),point=node("input","knowledge-point"),evidenceLabel=node("label","span-2"),evidence=node("textarea","student-evidence"),markerLabel=node("label","span-2"),marker=node("textarea","marker-guidance");
  q.maxLength=40;q.value=initial.questionRef||"";marks.type="number";marks.min="0";marks.step="0.5";marks.value=initial.marksLost||"";point.maxLength=140;point.value=initial.knowledgePoint||"";evidence.rows=2;evidence.maxLength=600;evidence.value=initial.evidence||"";marker.rows=2;marker.maxLength=600;marker.value=initial.markerGuidance||"";
  qLabel.append(node("span","field-question"),q);typeLabel.append(node("span","field-type"),select);marksLabel.append(node("span","field-marks"),marks);pointLabel.append(node("span","field-point"),point);evidenceLabel.append(node("span","field-evidence"),evidence);markerLabel.append(node("span","field-marker"),marker);
