function collectErrors(){return $$(".error-entry").map(entry=>({questionRef:entry.querySelector(".question-ref").value.trim(),type:entry.querySelector(".error-type").value,marksLost:entry.querySelector(".marks-lost").value,knowledgePoint:entry.querySelector(".knowledge-point").value.trim(),evidence:entry.querySelector(".student-evidence").value.trim(),markerGuidance:entry.querySelector(".marker-guidance").value.trim()})).filter(x=>x.questionRef||x.knowledgePoint||x.evidence||x.markerGuidance);}
