function buildReport(data){
  const topicResults=analyseDseTopics([data.autoText,data.notes,...data.errors.flatMap(item=>[item.knowledgePoint,item.evidence,item.markerGuidance]),...data.strengths.flatMap(item=>[item.concept,item.evidence])].filter(Boolean).join("\n")),dseTopics=topicResults.map(topicReport);
  const manualWeaknesses=[...data.errors.map(x=>weaknessFrom(x.type,x)),...data.signals.filter(k=>!data.errors.some(x=>x.type===k)).map(k=>weaknessFrom(k,{fallback:true}))],autoWeaknesses=manualWeaknesses.length?[]:topicResults.slice(0,3).map(result=>weaknessFrom(result.topic.errorType,{questionRef:t("autoExtracted"),knowledgePoint:result.topic.sub[language],evidence:(result.evidence||t("autoCaveat"))+" "+t("autoCaveat"),markerGuidance:result.topic.formula[language],fallback:!result.explicitWeak})),weaknesses=[...manualWeaknesses,...autoWeaknesses].slice(0,12);
  const keys=[...data.errors.map(x=>x.type),...data.signals,...topicResults.map(result=>result.topic.errorType)].filter((k,i,a)=>a.indexOf(k)===i).slice(0,6);
  const counts=[...data.errors.map(x=>x.type),...data.signals].reduce((map,key)=>(map[key]=(map[key]||0)+1,map),{}),topKey=Object.keys(counts).sort((a,b)=>counts[b]-counts[a])[0];
  const overview=[t("overview")(data.scope||t("wholePaper"),weaknesses.length)];if(data.score)overview.push(t("score")(data.score.awarded,data.score.total,data.score.percentage));overview.push(data.hasOriginal?t("sourceAvailable"):t("sourceUnavailable"),t("localNotice"));if(data.notes)overview.push(t("note")(data.notes));
  return{overview:overview.join(" "),summary:{strengths:data.strengths.length,weaknesses:weaknesses.length,topCause:topKey?t("types")[topKey]:(dseTopics[0]?.name||t("noCause"))},strengths:data.strengths.length?data.strengths:[{concept:t("strengthFallback"),evidence:t("strengthFallbackEvidence"),confidence:t("awaitingEvidence"),mastery:t("developingEvidence"),demonstratedSkill:t("strengthSkill"),nextStep:t("strengthExtension")}],weaknesses,dseTopics,remediation:keys.map((k,i)=>remedyFrom(k,i+1))};
}

