  const topics=$("#dseTopicsList");topics.replaceChildren();if(!(report.dseTopics||[]).length)topics.append(node("p","empty-history",t("noTopicResult")));(report.dseTopics||[]).forEach((item,index)=>{const card=node("article","report-card"),rank=node("div","topic-rank"),main=node("div"),confidence=node("span","topic-confidence",item.confidence),grid=node("div","detail-grid"),words=node("div","keyword-row");main.append(node("h4","",`Topic ${item.id} · ${item.name}`),node("p","",item.subtopic));rank.append(node("span","topic-number",String(index+1)),main,confidence);card.append(rank);[[t("topicEvidence"),item.evidence],[t("whyStrengthen"),item.why],[t("topicFormula"),item.formula],[t("topicPractice"),item.practice]].forEach(([label,value])=>{const box=node("div","detail-box");box.append(node("span","label",label),node("p","",value));grid.append(box);});item.keywords.forEach(word=>words.append(node("span","keyword",word)));card.append(grid,node("p","label",t("topicKeywords")),words);labelled(card,t("topicSuccess"),item.success,"evidence");topics.append(card);});
  const remediation=$("#remediationList");remediation.replaceChildren();report.remediation.forEach(item=>{const card=node("article","report-card"),top=node("div","report-card-top"),words=node("div","keyword-row"),details=node("div","detail-grid"),ladder=node("div","practice-ladder");top.append(node("h4","",item.priority+". "+item.focus),node("span","badge amber",t("priority")+" "+item.priority));item.keywords.forEach(w=>words.append(node("span","keyword",w)));[[t("prerequisite"),item.prerequisite||t("prerequisiteText")[item.key]||"—"],[t("formulaConditions"),item.formulaConditions||(item.formulas||[]).join(" · ")||t("noFormulaNeeded")]].forEach(([label,value])=>{const box=node("div","detail-box");box.append(node("span","label",label),node("p","",value));details.append(box);});const stages=item.practiceStages||[t("stages").recall,t("stages").guided,t("stages").transfer];[t("stage1"),t("stage2"),t("stage3")].forEach((label,index)=>{const stage=node("div","practice-stage");stage.append(node("strong","",label),node("p","",stages[index]));ladder.append(stage);});card.append(top,details,words);(item.formulas||[]).forEach(f=>card.append(node("p","formula",f)));card.append(ladder);labelled(card,t("practiceAction"),item.action);labelled(card,t("reviewSchedule"),item.reviewSchedule||t("reviewValue"));labelled(card,t("completionStandard"),item.successCheck);remediation.append(card);});
