function readHistory(){try{return JSON.parse(localStorage.getItem(historyKey)||"[]");}catch{return[];}}
function saveHistory(entry){localStorage.setItem(historyKey,JSON.stringify([entry,...readHistory().filter(x=>x.id!==entry.id)].slice(0,12)));renderHistory();}
function renderHistory(){const list=$("#historyList"),history=readHistory();list.replaceChildren();if(!history.length){list.append(node("p","empty-history",t("noHistory")));return;}history.forEach(item=>{const row=node("div","history-item"),open=node("button"),remove=node("button","text-button danger",t("delete"));open.type=remove.type="button";open.append(node("strong","",item.student+" · "+item.exam),node("small","",new Date(item.createdAt).toLocaleString(language==="zh-Hant"?"zh-HK":"en-GB")));open.addEventListener("click",()=>{renderReport(item.report,{student:item.student,detail:item.level+" · "+item.exam,status:t("savedLocally"),statusType:"saved"});$("#reportPanel").scrollIntoView({behavior:"smooth",block:"start"});});remove.style.flex="0 0 auto";remove.addEventListener("click",()=>{localStorage.setItem(historyKey,JSON.stringify(readHistory().filter(x=>x.id!==item.id)));renderHistory();});row.append(open,remove);list.append(row);});}
function files(){return{paper:$("#paperFile").files[0]||null,student:$("#studentFile").files[0]||null,marking:$("#markingFile").files[0]||null};}
function validPdf(file){return file&&(file.type==="application/pdf"||file.name.toLowerCase().endsWith(".pdf"))&&file.size<=15*1024*1024;}
function selectedSignals(){return $$('#signalGrid input[type="checkbox"]:checked').map(x=>x.value);}
function updateFile(input,metaId){const file=input.files[0];input.closest(".file-card").classList.toggle("has-file",Boolean(file));if(file)$(metaId).textContent=`${file.name} · ${(file.size/1024/1024).toFixed(1)} MB`;}
function setProcessing(active,message=""){$("#generateButton").disabled=active;$("#generateButton").querySelector("b").textContent=active?(message||t("processing")):t("generateReport");}
async function checkVisionBackend(){
  const label=$("#visionAvailability"),stage=$("#visionStage"),consent=$("#aiConsent"),consentLabel=$("#aiConsentLabel");visionBackendReady=false;stage.className="analysis-stage";
  if(!visionApiUrl){label.textContent=t("visionNotConnected");stage.classList.add("warning");consent.disabled=true;consentLabel.classList.add("disabled");return;}
  try{const response=await fetch(visionApiUrl,{method:"GET",mode:"cors",cache:"no-store"}),health=await response.json();if(!response.ok||!health.modelConfigured)throw new Error("Health check failed");visionBackendReady=true;label.textContent=t("visionConnected");stage.classList.add("active");consent.disabled=false;consentLabel.classList.remove("disabled");}
  catch(error){console.warn("Vision backend unavailable",error);label.textContent=t("visionNotConnected");stage.classList.add("warning");consent.disabled=true;consentLabel.classList.add("disabled");}
}
async function callVisionBackend(payload){
  const response=await fetch(visionApiUrl,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload),mode:"cors",cache:"no-store"}),data=await response.json().catch(()=>({}));
  if(!response.ok)throw new Error(data.error||`Visual analysis failed (${response.status})`);return data;
}
function canvasDataUrl(canvas){
  let quality=.76,data=canvas.toDataURL("image/jpeg",quality);while(data.length>1750000&&quality>.46){quality-=.1;data=canvas.toDataURL("image/jpeg",quality);}return data;
}
async function analyseVisualFile(file,role,context,onBatch){
  const pdfjs=await loadPdfJs(),pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;if(pdf.numPages>maxVisionPages)throw new Error(t("tooManyPages")(maxVisionPages));const evidence=[];
  for(let start=1;start<=pdf.numPages;start+=visionPagesPerBatch){const end=Math.min(pdf.numPages,start+visionPagesPerBatch-1),pages=[];for(let number=start;number<=end;number+=1){setProcessing(true,t("visualPreparing")(number,pdf.numPages));const page=await pdf.getPage(number),canvas=await pageCanvas(page,1500),local=pdfReadState[role]?.pageData?.find(item=>item.number===number);pages.push({pageNumber:number,image:canvasDataUrl(canvas),localText:local?.text||"",localSource:local?.source||"none"});}await onBatch();const result=await callVisionBackend({mode:"extract",language,role,context,pages});evidence.push(...(result.pageEvidence||[]));}
  return evidence;
}
async function runVisionAnalysis(chosen,context,teacherEvidence){
  const documents=[["student",chosen.student],["paper",chosen.paper],["marking",chosen.marking]].filter(([,file])=>file),totalBatches=documents.reduce((sum,[role])=>sum+Math.ceil((pdfReadState[role]?.pages||0)/visionPagesPerBatch),0);let completed=0,pageEvidence=[];
  for(const [role,file] of documents){const extracted=await analyseVisualFile(file,role,context,()=>{completed+=1;setProcessing(true,t("visualBatch")(completed,totalBatches));});pageEvidence=pageEvidence.concat(extracted);}
  setProcessing(true,t("visualSynthesising"));const result=await callVisionBackend({mode:"synthesize",language,context,teacherEvidence,pageEvidence,localTopics:analyseDseTopics(combinedExtractedText()).slice(0,6).map(item=>({id:item.topic.id,name:item.topic.name[language],evidence:item.evidence,score:item.score}))});
  if(!result.report?.overview||!Array.isArray(result.report.strengths)||!Array.isArray(result.report.weaknesses)||!Array.isArray(result.report.dseTopics)||!Array.isArray(result.report.remediation))throw new Error("Incomplete visual report");return result.report;
}

$("#diagnosticForm").addEventListener("submit",async event=>{
  event.preventDefault();const error=$("#formError");error.textContent="";const student=$("#studentCode").value.trim(),exam=$("#examTitle").value.trim(),chosen=files();
  if(!student||!exam){error.textContent=t("errIdentity");return;}if(!validPdf(chosen.student)||(chosen.paper&&!validPdf(chosen.paper))||(chosen.marking&&!validPdf(chosen.marking))){error.textContent=t("errPdf");return;}if(Object.values(chosen).reduce((s,f)=>s+(f?f.size:0),0)>40*1024*1024){error.textContent=t("errCombined");return;}
  const awarded=Number($("#marksAwarded").value),total=Number($("#totalMarks").value),hasScore=$("#marksAwarded").value!==""||$("#totalMarks").value!=="";if(hasScore&&(!(awarded>=0)||!(total>0)||awarded>total)){error.textContent=t("errScore");return;}
  if(Object.values(pdfReadState).some(state=>state?.status==="reading")){error.textContent=t("autoReadBusy");return;}
  const errors=collectErrors(),signals=selectedSignals(),autoText=combinedExtractedText(),useVision=visionBackendReady&&$("#aiConsent").checked;if(errors.some(x=>!x.questionRef||!x.evidence)){error.textContent=t("errPartial");return;}if(!errors.length&&!signals.length&&(!autoText||!analyseDseTopics(autoText).length)&&!useVision){error.textContent=visionBackendReady?t("visualConsentRequired"):(autoText?t("noTopicResult"):t("errEvidence"));return;}
  const data={level:$("#studentLevel").value,scope:$("#topicFocus").value.trim(),notes:$("#teacherNotes").value.trim(),strengths:parseStrengths($("#strengthEvidence").value),errors,signals,autoText,hasOriginal:Boolean(chosen.paper),score:hasScore?{awarded,total,percentage:awarded/total*100}:null},context={studentCode:student,level:data.level,examTitle:exam,scope:data.scope||t("wholePaper"),score:data.score,originalAvailable:Boolean(chosen.paper),markingAvailable:Boolean(chosen.marking)},teacherEvidence={errors,signals,strengths:data.strengths,notes:data.notes};let report,status=t("guided"),statusType="guided";
  try{setProcessing(true);if(useVision){report=await runVisionAnalysis(chosen,context,teacherEvidence);status=t("visualVerified");statusType="ai";}else{report=buildReport(data);if(!visionBackendReady)error.textContent=t("visionUnavailableFallback");}}
  catch(visionError){console.error("Visual analysis failed",visionError);if(!errors.length&&!signals.length&&!analyseDseTopics(autoText).length){error.textContent=`${t("visionFailedFallback")} ${visionError.message||""}`;return;}report=buildReport(data);error.textContent=t("visionFailedFallback");}
  finally{setProcessing(false);}
  const scoreLabel=data.score?" · "+data.score.percentage.toFixed(1)+"%":"";renderReport(report,{student,detail:data.level+" · "+exam+scoreLabel,status,statusType});saveHistory({id:crypto.randomUUID(),student,exam,level:data.level,createdAt:new Date().toISOString(),language,report});$("#reportPanel").scrollIntoView({behavior:"smooth",block:"start"});
});
